def reverseInsideBrackets(s):
    n = len(s)
    pair = [0] * n
    st = []
    for i, c in enumerate(s):
        if c == '(':
            st.append(i)
        elif c == ')':
            j = st.pop()
            pair[i] = j
            pair[j] = i
    out = []
    i, d = 0, 1
    while 0 <= i < n:
        c = s[i]
        if c == '(' or c == ')':
            i = pair[i]
            d = -d
        else:
            out.append(c)
        i += d
    return "".join(out)
